<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
import { ApiError } from '@/services/api'
import StatusBadge from '@/components/StatusBadge.vue'
const auth=useAuthStore(),router=useRouter(),displayName=ref(auth.user?.display_name||''),profileBusy=ref(false),profileMessage=ref(''),profileError=ref(''),currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref(''),passwordBusy=ref(false),passwordError=ref('')
const roleNames={super_admin:'总管理员',team_admin:'团队管理员',staff:'员工'}
async function saveProfile(){profileBusy.value=true;profileError.value='';profileMessage.value='';try{await auth.updateProfile(displayName.value);profileMessage.value='个人资料已更新。'}catch(e){profileError.value=e instanceof ApiError?e.message:'更新失败。'}finally{profileBusy.value=false}}
async function savePassword(){passwordError.value='';if(newPassword.value!==confirmPassword.value){passwordError.value='两次输入的新密码不一致。';return}passwordBusy.value=true;try{await auth.changePassword(currentPassword.value,newPassword.value);await router.replace({name:'login',query:{password:'changed'}})}catch(e){passwordError.value=e instanceof ApiError?e.message:'修改失败。'}finally{passwordBusy.value=false}}
</script>
<template><section><header class="page-header"><div><span class="eyebrow">Account</span><h1>个人设置</h1><p>管理显示名称和登录密码。</p></div></header><div class="settings-grid">
<article class="content-card profile-summary"><span class="avatar avatar-large">{{ auth.user?.display_name.slice(0,1) }}</span><h2>{{ auth.user?.display_name }}</h2><p>{{ auth.user?.email }}</p><StatusBadge :value="auth.user?.status||'active'"/><dl><div><dt>角色</dt><dd>{{ roleNames[auth.user?.role||'staff'] }}</dd></div><div><dt>团队 ID</dt><dd>{{ auth.user?.team_id||'平台级账号' }}</dd></div></dl></article>
<div class="settings-stack"><form class="content-card settings-form" @submit.prevent="saveProfile"><div class="card-heading"><div><h2>个人资料</h2><p>显示名称会出现在负责人和操作记录中。</p></div></div><div v-if="profileError" class="alert">{{ profileError }}</div><div v-if="profileMessage" class="alert alert-success">{{ profileMessage }}</div><label>邮箱<input :value="auth.user?.email" disabled/></label><label>显示名称<input v-model.trim="displayName" required maxlength="120"/></label><div class="form-actions"><button class="btn btn-primary" :disabled="profileBusy">{{ profileBusy?'保存中…':'保存资料' }}</button></div></form>
<form class="content-card settings-form" @submit.prevent="savePassword"><div class="card-heading"><div><h2>修改密码</h2><p>修改成功后，所有现有 Session 都会失效，需要重新登录。</p></div></div><div v-if="passwordError" class="alert">{{ passwordError }}</div><label>当前密码<input v-model="currentPassword" type="password" required autocomplete="current-password"/></label><div class="form-grid"><label>新密码<input v-model="newPassword" type="password" required minlength="12" autocomplete="new-password"/></label><label>确认新密码<input v-model="confirmPassword" type="password" required minlength="12" autocomplete="new-password"/></label></div><div class="form-actions"><button class="btn btn-primary" :disabled="passwordBusy">{{ passwordBusy?'更新中…':'更新密码' }}</button></div></form></div></div></section></template>
